#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath, pathToFileURL } from 'url';
import openapiTS, { astToString } from 'openapi-typescript';

/**
 * `npm run hub:types -- <openapi url or file>`: regenerates
 * `server/src/hub/hub-api.generated.ts` from the hub's
 * `/api/v1/openapi.json` (HD17). The generated file is committed, so the
 * CLI's types change only when someone runs this against a hub and reviews
 * the diff.
 */
class HubTypes {
  static OUTPUT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', 'server', 'src', 'hub', 'hub-api.generated.ts');

  static async run(argv) {
    const source = argv[0];
    if (!source) {
      console.error('Usage: npm run hub:types -- <openapi url or file>');
      console.error('  e.g. npm run hub:types -- http://localhost:8787/api/v1/openapi.json');
      process.exit(1);
    }
    const document = await HubTypes.read(source);
    const ast = await openapiTS(document, { exportType: true, alphabetize: true });
    const header = [
      '/**',
      ' * Generated by `npm run hub:types` from the hub\'s openapi.json. Do not edit:',
      ` * regenerate it instead. Hub API ${document.info?.version ?? ''}`.trimEnd() + '.',
      ' */',
      '',
    ].join('\n');
    fs.writeFileSync(HubTypes.OUTPUT, header + astToString(ast));
    console.log(`Wrote ${path.relative(process.cwd(), HubTypes.OUTPUT)} (${Object.keys(document.paths ?? {}).length} paths).`);
  }

  /** The document as JSON, from a URL or a file path. */
  static async read(source) {
    if (/^https?:\/\//.test(source)) {
      const response = await fetch(source, { signal: AbortSignal.timeout(20_000) });
      if (!response.ok) {
        throw new Error(`${source} answered ${response.status}`);
      }
      return response.json();
    }
    const file = source.startsWith('file:') ? fileURLToPath(source) : path.resolve(source);
    if (!fs.existsSync(file)) {
      throw new Error(`${pathToFileURL(file).pathname} doesn't exist.`);
    }
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  }
}

HubTypes.run(process.argv.slice(2)).catch((err) => {
  console.error(err?.message ?? err);
  process.exit(1);
});
